/* NAMO QMES mobile-only workorder + production process workspace — 2026-09-03 */
(function installQmesMobileProduction(){
  'use strict';
  if(window.__QMES_MOBILE_PRODUCTION_20260903__)return;
  window.__QMES_MOBILE_PRODUCTION_20260903__=true;
  const tab=String(new URLSearchParams(location.search).get('tab')||'');
  if(!['woIssue','prodProcess'].includes(tab))return;

  const clean=v=>String(v==null?'':v).replace(/\s+/g,' ').trim();
  const num=v=>{const n=Number(String(v??'').replace(/,/g,''));return Number.isFinite(n)?n:0;};
  const fmt=v=>Number(v||0).toLocaleString('ko-KR',{maximumFractionDigits:3});
  const esc=v=>clean(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const parse=row=>{let p=row?.payload;if(p&&typeof p==='object')return p;if(typeof p==='string'){try{return JSON.parse(p)}catch(_){}}return{};};
  const stamp=v=>{const d=new Date(v);return Number.isNaN(d.getTime())?(clean(v)||'-'):d.toLocaleString('ko-KR',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});};
  const first=(o,keys)=>{for(const k of keys){const v=o?.[k];if(v!==undefined&&v!==null&&clean(v)!=='')return v;}return'';};
  const state={rows:[],orders:[],processes:new Map(),workers:[],query:'',status:'',selected:''};

  async function api(path){
    const r=await fetch(path,{credentials:'same-origin',cache:'no-store'});const p=await r.json().catch(()=>null);
    if(r.status===401){location.replace('/index.html?mobileLogin=1');throw new Error('AUTH');}
    if(!r.ok||p?.success===false)throw new Error(p?.message||`HTTP ${r.status}`);
    return p?.data!==undefined?p.data:p;
  }

  function orderFromRow(row){
    const p=parse(row);if(p.deleted)return null;
    const key=clean(row.record_key);
    if(key.startsWith('process:')||key.startsWith('worker:'))return null;
    const doc=p.doc&&typeof p.doc==='object'?p.doc:{};const batch=p.batch&&typeof p.batch==='object'?p.batch:{};const lotRecord=p.lotRecord&&typeof p.lotRecord==='object'?p.lotRecord:{};
    const lot=clean(p.lotNo||p.lot||p.productionLot||batch.no||batch.lot||batch.lotNo||key).toUpperCase();if(!lot)return null;
    const item=clean(batch.itemName||batch.item||batch.product||doc.itemName||doc.item||doc.product||lotRecord.itemName||lotRecord.item||'-');
    const date=clean(batch.date||batch.prodDate||batch.productionDate||doc.date||p.date||row.updated_at).slice(0,10);
    const plan=num(batch.plan??batch.planQty??batch.qty??doc.planQty??doc.plan??doc.qty);
    const done=num(batch.done??batch.productionQty??batch.actualQty??lotRecord.qty);
    const status=clean(lotRecord.status||batch.status||batch.state||doc.status||'대기');
    const type=clean(batch.productionType||batch.type||doc.productionType||doc.type||'-');
    const equipment=clean(batch.equipment||doc.equipment||doc.equipmentName||doc.machine||doc.tank||doc.eq||'-');
    const candidates=[lotRecord.materials,doc.inputs,doc.materials,doc.materialRows,doc.rawMaterials,doc.recipeMaterials,doc.ingredients];
    const source=candidates.find(Array.isArray)||[];
    const materials=source.map(m=>({name:clean(first(m,['name','material','materialName','itemName']))||'-',lot:clean(first(m,['lot','lotNo','materialLot','supplierLot'])).toUpperCase()||'-',qty:first(m,['act','actualQty','usedQty','inputQty','qty','std']),supplier:clean(m.supplier||m.supName||'')}));
    return{key,lot,item,date,plan,done,status,type,equipment,materials,payload:p,updatedAt:row.updated_at};
  }

  function processFromRow(row){const key=clean(row.record_key);if(!key.startsWith('process:'))return null;const p=parse(row);const lot=clean(p.lot||key.slice(8)).toUpperCase();if(!lot)return null;return{lot,key,payload:p,updatedAt:row.updated_at};}
  function tone(s){s=clean(s);if(/불합격|부적합|HOLD|중단|이상/.test(s))return'danger';if(/진행|작업중/.test(s))return'active';if(/완료|생산완료/.test(s))return'ok';return'wait';}
  function progress(order){if(order.plan>0)return Math.max(0,Math.min(100,order.done/order.plan*100));const p=state.processes.get(order.lot)?.payload;const steps=Array.isArray(p?.steps)?p.steps:[];return steps.length?steps.filter(s=>clean(s.status)==='완료').length/steps.length*100:0;}
  function processStatus(order){return clean(state.processes.get(order.lot)?.payload?.status||order.status||'대기');}

  function style(){if(document.getElementById('qmp-style'))return;const el=document.createElement('style');el.id='qmp-style';el.textContent=`
  .qmp{display:flex;flex-direction:column;gap:10px}.qmp-tools{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px}.qmp-tools input,.qmp-filter{height:44px;border:1px solid #d9e2e8;border-radius:10px;background:#fff;color:#1b344a;padding:0 11px;font-size:14px;outline:0}.qmp-btn{min-height:42px;padding:0 11px;border:1px solid #d9e2e8;border-radius:9px;background:#fff;color:#31506a;font-size:8.8px;font-weight:950;cursor:pointer}.qmp-btn.primary{background:#0d5eb8;border-color:#0d5eb8;color:#fff}.qmp-filterbar{display:grid;grid-template-columns:1fr auto auto;gap:7px}.qmp-note{padding:10px 11px;border:1px solid #dce4eb;border-radius:10px;background:#fff;color:#65778a;font-size:8.6px;font-weight:750;line-height:1.55}.qmp-note.error{border-color:#eccfd4;background:#fff7f8;color:#a23342}.qmp-list{display:grid;grid-template-columns:1fr;gap:9px}.qmp-card{overflow:hidden;border:1px solid #dce4eb;border-radius:12px;background:#fff;box-shadow:0 3px 10px rgba(18,42,64,.025)}.qmp-head{display:flex;align-items:flex-start;gap:9px;padding:12px 11px 10px;border-bottom:1px solid #edf1f4}.qmp-no{flex:0 0 34px;width:34px;height:34px;border-radius:9px;background:#edf5fa;color:#176b9c;display:grid;place-items:center;font-size:8.8px;font-weight:950}.qmp-title{min-width:0;flex:1}.qmp-title strong{display:block;color:#18334a;font-size:12.4px;font-weight:950;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.qmp-title span{display:block;margin-top:4px;color:#7b8997;font-size:8.5px;font-weight:750;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.qmp-badge{flex:none;padding:5px 7px;border-radius:6px;background:#eef2f5;color:#586879;font-size:7.5px;font-weight:950}.qmp-badge.active{background:#e4efff;color:#0759c9}.qmp-badge.ok{background:#e6f7e3;color:#277c2b}.qmp-badge.danger{background:#fde8eb;color:#aa3140}.qmp-badge.wait{background:#fff2dc;color:#996000}.qmp-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));padding:3px 11px 8px}.qmp-field{min-width:0;padding:8px 6px 7px;border-bottom:1px solid #f0f3f5}.qmp-field:nth-child(odd){padding-left:0}.qmp-field:nth-child(even){padding-right:0}.qmp-field small{display:block;color:#929daa;font-size:7.4px;font-weight:850}.qmp-field b{display:block;margin-top:4px;color:#344b61;font-size:9.5px;font-weight:900;line-height:1.35;word-break:break-word}.qmp-progress{height:5px;margin:0 11px 8px;border-radius:5px;background:#edf1f4;overflow:hidden}.qmp-progress i{display:block;height:100%;background:#2480b9;border-radius:5px}.qmp-actions{display:flex;justify-content:flex-end;gap:6px;padding:9px 11px 10px;background:#fbfcfd}.qmp-actions .qmp-btn{min-height:34px;padding:0 9px}.qmp-detail{display:none;padding:0 11px 11px;border-top:1px solid #edf1f4}.qmp-card.open .qmp-detail{display:block}.qmp-section{margin-top:10px;border:1px solid #e1e7ec;border-radius:10px;overflow:hidden}.qmp-section h3{margin:0;padding:9px 10px;background:#f8fafc;border-bottom:1px solid #e9eef2;color:#334c62;font-size:9.5px;font-weight:950}.qmp-material,.qmp-step{padding:9px 10px;border-bottom:1px solid #edf1f4}.qmp-material:last-child,.qmp-step:last-child{border-bottom:0}.qmp-material strong,.qmp-step strong{display:block;color:#29465e;font-size:9.5px;font-weight:950}.qmp-material span,.qmp-step span{display:block;margin-top:4px;color:#738295;font-size:8.2px;font-weight:750;line-height:1.45}.qmp-step-row{display:flex;align-items:center;gap:8px}.qmp-step-no{flex:0 0 25px;width:25px;height:25px;border-radius:7px;background:#eef4f7;color:#436178;display:grid;place-items:center;font-size:7.5px;font-weight:950}.qmp-step-body{min-width:0;flex:1}.qmp-empty{padding:44px 18px;text-align:center;border:1px dashed #d5dee5;border-radius:12px;background:#fff;color:#8794a0}.qmp-empty strong{display:block;color:#53687a;font-size:12px;font-weight:950}.qmp-empty span{display:block;margin-top:6px;font-size:8.8px;font-weight:750;line-height:1.6}
  @media(min-width:700px){.qmp-list{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.qmp-tools input{height:48px}.qmp-btn{min-height:46px;font-size:9.7px}.qmp-field small{font-size:8.4px}.qmp-field b{font-size:10.5px}}
  `;document.head.appendChild(el);}

  function shell(title,desc){const pt=document.getElementById('pageTitle'),ht=document.getElementById('headTitle'),pd=document.getElementById('pageDesc'),toolbar=document.getElementById('toolbar'),content=document.querySelector('.content');if(pt)pt.textContent=title;if(ht)ht.textContent=title;if(pd)pd.textContent=desc;if(toolbar)toolbar.style.display='none';if(content)content.innerHTML='<div id="qmpRoot" class="qmp"></div>';}
  function summary(a,av,b,bv,c,cv){const x=document.getElementById('sumAll'),y=document.getElementById('sum2'),z=document.getElementById('sum3');const xl=x?.parentElement?.querySelector('span'),yl=document.getElementById('sum2Label'),zl=document.getElementById('sum3Label');if(xl)xl.textContent=a;if(yl)yl.textContent=b;if(zl)zl.textContent=c;if(x)x.textContent=av;if(y)y.textContent=bv;if(z)z.textContent=cv;}
  function loading(show,text){const box=document.getElementById('loading'),label=document.getElementById('loadingText');if(label&&text)label.textContent=text;if(box)box.classList.toggle('show',!!show);}
  function go(next){location.assign(`/mobile-work.html?tab=${encodeURIComponent(next)}&v=20260903-prod1`);}

  function filtered(){const q=clean(state.query).toLowerCase();return state.orders.filter(o=>(!state.status||processStatus(o)===state.status)&&(!q||[o.lot,o.item,o.status,o.type,o.equipment].join(' ').toLowerCase().includes(q)));}
  function card(order,index,processView){const p=state.processes.get(order.lot)?.payload||{};const st=processStatus(order),pct=progress(order),steps=Array.isArray(p.steps)?p.steps:[];const workers=(Array.isArray(p.workers)?p.workers:[]).map(w=>clean(w.name||w)).filter(Boolean);const mats=order.materials||[];return `<article class="qmp-card" data-lot="${esc(order.lot)}"><div class="qmp-head"><div class="qmp-no">${String(index+1).padStart(2,'0')}</div><div class="qmp-title"><strong>${esc(order.item||'-')}</strong><span>${esc(order.lot)} · ${esc(order.date||'-')}</span></div><span class="qmp-badge ${tone(st)}">${esc(st)}</span></div><div class="qmp-fields"><div class="qmp-field"><small>생산구분</small><b>${esc(order.type||'-')}</b></div><div class="qmp-field"><small>설비</small><b>${esc(order.equipment||'-')}</b></div><div class="qmp-field"><small>계획 / 실적</small><b>${fmt(order.plan)} / ${fmt(order.done)} kg</b></div><div class="qmp-field"><small>진척률</small><b>${pct.toFixed(1)}%</b></div>${processView?`<div class="qmp-field"><small>작업자</small><b>${esc(workers.join(' · ')||'-')}</b></div><div class="qmp-field"><small>최종갱신</small><b>${esc(stamp(state.processes.get(order.lot)?.updatedAt||order.updatedAt))}</b></div>`:`<div class="qmp-field"><small>투입 원료</small><b>${mats.length}종</b></div><div class="qmp-field"><small>최종갱신</small><b>${esc(stamp(order.updatedAt))}</b></div>`}</div><div class="qmp-progress"><i style="width:${pct}%"></i></div><div class="qmp-actions"><button class="qmp-btn" data-detail="${esc(order.lot)}">상세</button><button class="qmp-btn" data-trace="${esc(order.lot)}">LOT 추적</button>${processView?'<button class="qmp-btn primary" data-pqc="1">PQC</button>':'<button class="qmp-btn primary" data-process="1">공정현황</button>'}</div><div class="qmp-detail">${processView?`<section class="qmp-section"><h3>공정 단계</h3>${steps.length?steps.map((s,i)=>`<div class="qmp-step"><div class="qmp-step-row"><div class="qmp-step-no">${i+1}</div><div class="qmp-step-body"><strong>${esc(s.name||`공정 ${i+1}`)} <span class="qmp-badge ${tone(s.status)}" style="display:inline-block;margin-left:5px">${esc(s.status||'대기')}</span></strong><span>${esc(s.equipment||'-')} · 시작 ${esc(stamp(s.startAt))} · 종료 ${esc(stamp(s.endAt))}${s.resultQty?` · 실적 ${esc(s.resultQty)}`:''}</span></div></div></div>`).join(''):'<div class="qmp-material"><span>아직 저장된 생산공정 기록이 없습니다.</span></div>'}</section>`:`<section class="qmp-section"><h3>투입 원료 / LOT</h3>${mats.length?mats.map(m=>`<div class="qmp-material"><strong>${esc(m.name)} · ${esc(m.lot)}</strong><span>${m.supplier?`공급사 ${esc(m.supplier)} · `:''}투입 ${esc(m.qty===''?'-':m.qty)}</span></div>`).join(''):'<div class="qmp-material"><span>작업지시에 연결된 원료 LOT 정보가 없습니다.</span></div>'}</section>`}<div class="qmp-note" style="margin-top:9px">모바일 화면은 중앙 공유 작업지시/공정 기록을 읽어 표시합니다. PC 작업 중 데이터 충돌을 막기 위해 이번 단계에서는 공정 시작·완료 편집은 제공하지 않습니다.</div></div></article>`;}

  function render(processView){const root=document.getElementById('qmpRoot');if(!root)return;const rows=filtered();const statuses=Array.from(new Set(state.orders.map(processStatus))).filter(Boolean).sort();root.innerHTML=`<div class="qmp-tools"><input id="qmpSearch" type="search" placeholder="LOT · 제품명 · 설비 검색" value="${esc(state.query)}"><button class="qmp-btn primary" id="qmpRefresh">새로고침</button></div><div class="qmp-filterbar"><select id="qmpStatus" class="qmp-filter"><option value="">전체 상태</option>${statuses.map(s=>`<option ${state.status===s?'selected':''}>${esc(s)}</option>`).join('')}</select><button class="qmp-btn" id="qmpInventory">재고</button><button class="qmp-btn" id="qmpTrace">LOT 추적</button></div><div class="qmp-note">${processView?'생산공정 공유 기록(process:LOT)과 작업지시를 연결해 현장 진행상태를 표시합니다.':'공용 DB 작업지시 기준으로 제품·생산 LOT·원료 LOT·계획/실적을 모바일에 맞게 표시합니다.'}</div><div class="qmp-list">${rows.length?rows.map((o,i)=>card(o,i,processView)).join(''):'<div class="qmp-empty"><strong>조건에 맞는 작업지시가 없습니다.</strong><span>검색어 또는 상태 필터를 변경해 주세요.</span></div>'}</div>`;
    document.getElementById('qmpSearch')?.addEventListener('input',e=>{state.query=e.target.value;render(processView);});document.getElementById('qmpStatus')?.addEventListener('change',e=>{state.status=e.target.value;render(processView);});document.getElementById('qmpRefresh')?.addEventListener('click',load);document.getElementById('qmpInventory')?.addEventListener('click',()=>go('inv'));document.getElementById('qmpTrace')?.addEventListener('click',()=>go('trace'));
    root.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>b.closest('.qmp-card')?.classList.toggle('open')));root.querySelectorAll('[data-trace]').forEach(b=>b.addEventListener('click',()=>{try{sessionStorage.setItem('qmes_mobile_trace_lot',b.dataset.trace);}catch(_){}go('trace');}));root.querySelectorAll('[data-process]').forEach(b=>b.addEventListener('click',()=>go('prodProcess')));root.querySelectorAll('[data-pqc]').forEach(b=>b.addEventListener('click',()=>go('pqc')));
  }

  async function load(){loading(true,'작업지시·생산공정 데이터를 불러오는 중입니다.');try{const rows=await api('/api/qmes-sync/workorder');state.rows=Array.isArray(rows)?rows:[];state.orders=state.rows.map(orderFromRow).filter(Boolean);state.processes=new Map(state.rows.map(processFromRow).filter(Boolean).map(p=>[p.lot,p]));state.workers=state.rows.filter(r=>clean(r.record_key).startsWith('worker:')).map(r=>parse(r));const active=state.orders.filter(o=>/진행|작업중/.test(processStatus(o))).length,complete=state.orders.filter(o=>/완료|생산완료/.test(processStatus(o))).length;summary('공유 작업지시',String(state.orders.length),'진행중',String(active),'완료',String(complete));render(tab==='prodProcess');}catch(e){render(tab==='prodProcess');if(e.message!=='AUTH'){const root=document.getElementById('qmpRoot');if(root)root.insertAdjacentHTML('afterbegin',`<div class="qmp-note error">데이터 조회 실패: ${esc(e.message)}</div>`);}}finally{loading(false);}}

  style();shell(tab==='prodProcess'?'생산공정':'작업지시','공용 DB · 모바일/iPad 생산 업무 조회');setTimeout(load,160);
})();
